/*
 * SHADER BACKGROUND — "Neuro Noise" (Paper Shaders, Apache-2.0),
 * generated by the 21st.dev Shader Builder and ported to dependency-free
 * vanilla JS for this static site. Renders one WebGL canvas (#shaderbg)
 * fixed behind the ASCII dandelion (#field). Recoloured to a visible
 * gray-on-black, with the original cursor interaction kept: hovering makes
 * the filaments ripple/move around the pointer.
 * If WebGL is unavailable it silently no-ops (the page keeps its dark bg).
 */
(function () {
  "use strict";
  var canvas = document.getElementById("shaderbg");
  if (!canvas) return;
  var reduce = matchMedia("(prefers-reduced-motion:reduce)").matches;

  var VERT = "attribute vec2 a_position;\n" +
    "void main(){ gl_Position = vec4(a_position,0.0,1.0); }";

  var FRAG = [
"#ifdef GL_FRAGMENT_PRECISION_HIGH",
"precision highp float;",
"#else",
"precision mediump float;",
"#endif",
"uniform vec3 u_colors[8];",
"uniform vec4 u_scene;",     // resolution.xy, time, colour count
"uniform vec4 u_shape;",     // scale, intensity, paramA, warp
"uniform vec4 u_surface;",   // detail, contrast, brightness, saturation
"uniform vec4 u_finish;",    // hue, vignette, blur, grain
"uniform vec4 u_transform;", // seed, rotation, drift, OKLab toggle
"uniform vec4 u_space;",     // offset.xy, pointer.xy
"uniform vec4 u_cursor;",
"#define u_resolution u_scene.xy",
"#define u_time u_scene.z",
"#define u_colorCount u_scene.w",
"#define u_scale u_shape.x",
"#define u_intensity u_shape.y",
"#define u_paramA u_shape.z",
"#define u_warp u_shape.w",
"#define u_detail u_surface.x",
"#define u_contrast u_surface.y",
"#define u_brightness u_surface.z",
"#define u_saturation u_surface.w",
"#define u_hue u_finish.x",
"#define u_vignette u_finish.y",
"#define u_blur u_finish.z",
"#define u_grain u_finish.w",
"#ifdef GL_FRAGMENT_PRECISION_HIGH",
"#define u_seed u_transform.x",
"#else",
"#define u_seed mod(u_transform.x, 31.0)",
"#endif",
"#define u_rotate u_transform.y",
"#define u_drift u_transform.z",
"#define u_oklab u_transform.w",
"#define u_offset u_space.xy",
"#define u_mouse u_space.zw",
"#define u_cursorPresence u_cursor.x",
"#define u_cursorEffect u_cursor.y",
"#define u_cursorStrength u_cursor.z",
"#define u_cursorRadius u_cursor.w",
"float hash21(vec2 p){",
"#ifndef GL_FRAGMENT_PRECISION_HIGH",
"  p = mod(p, 31.0);",
"#endif",
"  p = fract(p * vec2(234.34, 435.345));",
"  p += dot(p, p + 34.23);",
"  return fract(p.x * p.y);",
"}",
"float grainHash(vec2 p){",
"  vec3 p3 = fract(vec3(p.xyx) * 0.1031);",
"  p3 += dot(p3, p3.yzx + 33.33);",
"  return fract((p3.x + p3.y) * p3.z);",
"}",
"float noise(vec2 p){",
"  vec2 i = floor(p); vec2 f = fract(p);",
"  vec2 u = f * f * (3.0 - 2.0 * f);",
"  return mix(mix(hash21(i), hash21(i + vec2(1.0,0.0)), u.x),",
"             mix(hash21(i + vec2(0.0,1.0)), hash21(i + vec2(1.0,1.0)), u.x), u.y);",
"}",
"float fbm(vec2 p){",
"  float v = 0.0; float a = 0.5;",
"  for (int i = 0; i < 5; i++){ v += a * noise(p); p = p * 2.03 + vec2(17.0,9.2); a *= 0.5; }",
"  return v;",
"}",
"vec3 palette(float x){",
"  float n = max(u_colorCount - 1.0, 1.0);",
"  float f = clamp(x, 0.0, 1.0) * n;",
"  vec3 col = u_colors[0];",
"  for (int i = 0; i < 7; i++){",
"    if (float(i) < n) col = mix(col, u_colors[i + 1], smoothstep(0.0, 1.0, clamp(f - float(i), 0.0, 1.0)));",
"  }",
"  return col;",
"}",
"vec3 shade(vec2 uv, vec2 p, float t){",
"  vec2 q = p * (1.6 + u_intensity * 2.4);",
"  float field = 0.0; float weight = 0.55;",
"  for (int i = 0; i < 6; i++){",
"    float fi = float(i);",
"    q += vec2(sin(q.y * (1.7 + fi * 0.09) + t * (0.35 + fi * 0.04) + u_seed),",
"              cos(q.x * (1.5 + fi * 0.11) - t * (0.28 + fi * 0.03))) * (0.22 + u_intensity * 0.14);",
"    float filaments = abs(sin(q.x + q.y + fi * 0.72));",
"    field += weight / (0.08 + filaments);",
"    weight *= 0.62;",
"    q = q.yx * vec2(-1.08, 1.04);",
"  }",
"  float glow = 1.0 - exp(-field * (0.018 + u_paramA * 0.04));",
"  return palette(clamp(glow, 0.0, 1.0));",
"}",
"void main(){",
"  vec2 uv = gl_FragCoord.xy / u_resolution.xy;",
"  vec2 screenUv = uv;",
"  vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution.xy) / min(u_resolution.x, u_resolution.y);",
"  float cursorMask = 0.0;",
"  if (u_cursorPresence > 0.001) {",
"    vec2 cursor = (0.5 * u_mouse * u_resolution.xy) / min(u_resolution.x, u_resolution.y);",
"    vec2 cursorDelta = p - cursor;",
"    if (u_cursorEffect < 0.5) {",
"      p += cursor * u_cursorPresence * u_cursorStrength * 0.55;",
"    } else {",
"      float cursorDistance = length(cursorDelta);",
"      vec2 cursorDirection = cursorDelta / max(cursorDistance, 0.0001);",
"      cursorMask = u_cursorPresence * (1.0 - smoothstep(0.0, u_cursorRadius, cursorDistance));",
"      if (u_cursorEffect < 1.5) {",
"        p -= cursorDirection * cursorMask * u_cursorStrength * 0.24;",
"      } else if (u_cursorEffect < 2.5) {",
"        float cursorAngle = cursorMask * u_cursorStrength * 2.2;",
"        float cc = cos(cursorAngle), cs = sin(cursorAngle);",
"        p = cursor + mat2(cc, -cs, cs, cc) * cursorDelta;",
"      } else if (u_cursorEffect < 3.5) {",
"        float ripple = sin(cursorDistance / max(u_cursorRadius, 0.001) * 18.0 - u_time * 5.0);",
"        p -= cursorDirection * ripple * cursorMask * u_cursorStrength * 0.07;",
"      }",
"    }",
"  }",
"  uv = p * min(u_resolution.x, u_resolution.y) / u_resolution.xy + 0.5;",
"  p *= u_scale;",
"  if (abs(u_rotate) > 0.0001){ float cr = cos(u_rotate), sr = sin(u_rotate); p = mat2(cr,-sr,sr,cr) * p; }",
"  p += u_offset;",
"  if (u_drift > 0.0001) p += u_drift * vec2(sin(u_time * 0.31), cos(u_time * 0.23));",
"  if (u_warp > 0.0){ p += u_warp * (vec2(fbm(p * u_detail + u_seed), fbm(p * u_detail + vec2(5.2,1.3))) - 0.5); }",
"  vec3 col;",
"  if (u_blur > 0.0){",
"    float e = u_blur; float pe = e * u_scale;",
"    vec2 uvE = vec2(e) * min(u_resolution.x, u_resolution.y) / u_resolution.xy;",
"    col  = shade(uv, p, u_time) * 0.36;",
"    col += shade(uv + vec2(uvE.x,0.0), p + vec2(pe,0.0), u_time) * 0.16;",
"    col += shade(uv - vec2(uvE.x,0.0), p - vec2(pe,0.0), u_time) * 0.16;",
"    col += shade(uv + vec2(0.0,uvE.y), p + vec2(0.0,pe), u_time) * 0.16;",
"    col += shade(uv - vec2(0.0,uvE.y), p - vec2(0.0,pe), u_time) * 0.16;",
"  } else { col = shade(uv, p, u_time); }",
"  if (abs(u_contrast - 1.0) > 0.0001) col = (col - 0.5) * u_contrast + 0.5;",
"  if (abs(u_saturation - 1.0) > 0.0001){ float luma = dot(col, vec3(0.299,0.587,0.114)); col = mix(vec3(luma), col, u_saturation); }",
"  if (abs(u_brightness) > 0.0001) col += u_brightness;",
"  if (u_vignette > 0.0001){ float vd = length(screenUv - 0.5) * 1.41421356; col *= 1.0 - u_vignette * smoothstep(0.35, 1.0, vd); }",
"  if (u_cursorPresence > 0.001 && u_cursorEffect > 3.5) col += (vec3(0.18) + col * 0.12) * cursorMask * u_cursorStrength;",
"  if (u_grain > 0.0001) col += (grainHash(gl_FragCoord.xy + vec2(u_seed * 17.0, u_seed * 31.0)) - 0.5) * u_grain;",
"  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);",
"}"
].join("\n");

  // Visible gray-on-black recolour (black base → mid grays). colorCount = 4.
  var UNIFORMS = {
    colors: [
      [0.000, 0.000, 0.000],
      [0.140, 0.140, 0.155],
      [0.280, 0.280, 0.300],
      [0.460, 0.460, 0.490],
      [0.460, 0.460, 0.490],
      [0.460, 0.460, 0.490],
      [0.460, 0.460, 0.490],
      [0.460, 0.460, 0.490]
    ],
    colorCount: 4,
    scale: 1.26,
    intensity: 0.35,
    paramA: 0.28,
    warp: 0.0,
    detail: 1.824,
    contrast: 1.03,
    brightness: 0.01,
    saturation: 1.0,      // grays: keep neutral
    hue: 0.0,
    vignette: 0.0,
    blur: 0.0012,
    grain: 0.06,
    seed: 1.0,
    rotate: 0.0,
    offsetX: 0.0,
    offsetY: 0.0,
    drift: 0.204,
    oklab: 0.0,
    // cursor interaction — filaments ripple around the pointer (original preset)
    cursorEnabled: true,
    cursorEffect: 3.0,     // 0 push · 1 attract · 2 swirl · 3 ripple · 4 glow
    cursorStrength: 0.55,
    cursorRadius: 0.5,
    timeScale: reduce ? 0.0 : 0.6   // drift frozen under reduced-motion
  };

  var gl = canvas.getContext("webgl", { antialias: false });
  if (!gl) return;

  function compile(type, src) {
    var s = gl.createShader(type);
    gl.shaderSource(s, src);
    gl.compileShader(s);
    return s;
  }
  var program = gl.createProgram();
  var vs = compile(gl.VERTEX_SHADER, VERT);
  var fs = compile(gl.FRAGMENT_SHADER, FRAG);
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  gl.useProgram(program);

  var quad = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, quad);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  var aloc = gl.getAttribLocation(program, "a_position");
  gl.enableVertexAttribArray(aloc);
  gl.vertexAttribPointer(aloc, 2, gl.FLOAT, false, 0, 0);

  var uni = {
    colors: gl.getUniformLocation(program, "u_colors"),
    scene: gl.getUniformLocation(program, "u_scene"),
    shape: gl.getUniformLocation(program, "u_shape"),
    surface: gl.getUniformLocation(program, "u_surface"),
    finish: gl.getUniformLocation(program, "u_finish"),
    transform: gl.getUniformLocation(program, "u_transform"),
    space: gl.getUniformLocation(program, "u_space"),
    cursor: gl.getUniformLocation(program, "u_cursor")
  };
  var flat = [];
  for (var i = 0; i < UNIFORMS.colors.length; i++) flat.push.apply(flat, UNIFORMS.colors[i]);
  gl.uniform3fv(uni.colors, new Float32Array(flat));
  gl.uniform4f(uni.shape, UNIFORMS.scale, UNIFORMS.intensity, UNIFORMS.paramA, UNIFORMS.warp);
  gl.uniform4f(uni.surface, UNIFORMS.detail, UNIFORMS.contrast, UNIFORMS.brightness, UNIFORMS.saturation);
  gl.uniform4f(uni.finish, UNIFORMS.hue, UNIFORMS.vignette, UNIFORMS.blur, UNIFORMS.grain);
  gl.uniform4f(uni.transform, UNIFORMS.seed, UNIFORMS.rotate, UNIFORMS.drift, UNIFORMS.oklab);
  gl.uniform4f(uni.cursor, 0, UNIFORMS.cursorEffect, UNIFORMS.cursorStrength, UNIFORMS.cursorRadius);

  // ---- pointer state (the shader sits behind the dandelion but tracks the
  // window pointer, so hover still moves the filaments) ----
  var targetX = 0, targetY = 0, targetPresence = 0;
  var mouseX = 0, mouseY = 0, cursorPresence = 0;
  var pointerKnown = false, pointerClientX = 0, pointerClientY = 0;
  var bounds = canvas.getBoundingClientRect();

  var raf = 0, lastNow = null, disposed = false;
  var visible = document.visibilityState === "visible";
  var inView = true;
  var paused = false;   // WORK detail overlay open → stop rendering (nothing visible behind it)
  var start = performance.now();
  var timeAnimated = Math.abs(UNIFORMS.timeScale) > 0.0001;

  function resizeCanvas() {
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    var rawW = Math.max(1, Math.round(canvas.clientWidth * dpr));
    var rawH = Math.max(1, Math.round(canvas.clientHeight * dpr));
    var pixelScale = Math.min(1, Math.sqrt(2000000 / Math.max(1, rawW * rawH)));
    var w = Math.max(1, Math.round(rawW * pixelScale));
    var h = Math.max(1, Math.round(rawH * pixelScale));
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w; canvas.height = h;
      gl.viewport(0, 0, w, h);
    }
  }

  function requestRender() {
    if (!disposed && visible && inView && !paused && raf === 0) raf = requestAnimationFrame(render);
  }

  function updatePointerTarget() {
    if (!pointerKnown || bounds.width === 0 || bounds.height === 0) return;
    var inside = pointerClientX >= bounds.left && pointerClientX <= bounds.right &&
                 pointerClientY >= bounds.top && pointerClientY <= bounds.bottom;
    if (!inside) { targetPresence = 0; requestRender(); return; }
    var nextX = ((pointerClientX - bounds.left) / bounds.width) * 2 - 1;
    var nextY = -(((pointerClientY - bounds.top) / bounds.height) * 2 - 1);
    if (targetPresence === 0 && cursorPresence < 0.01) { mouseX = nextX; mouseY = nextY; }
    targetX = nextX; targetY = nextY; targetPresence = 1;
    requestRender();
  }
  function onPointerMove(e) {
    pointerKnown = true;
    pointerClientX = e.clientX; pointerClientY = e.clientY;
    bounds = canvas.getBoundingClientRect();
    updatePointerTarget();
  }
  function onPointerLeave() { pointerKnown = false; targetPresence = 0; requestRender(); }

  function render(now) {
    raf = 0;
    if (disposed || !visible || !inView || paused) return;
    var dt = lastNow === null ? 0 : Math.min((now - lastNow) / 1000, 0.1);
    lastNow = now;
    var follow = 1 - Math.exp(-12 * dt);
    mouseX += (targetX - mouseX) * follow;
    mouseY += (targetY - mouseY) * follow;
    cursorPresence += (targetPresence - cursorPresence) * follow;
    resizeCanvas();
    var _tp = window.HeroPerf ? HeroPerf.t() : 0;   // perf HUD (submit time only — GPU work is async)
    gl.uniform4f(uni.scene, canvas.width, canvas.height,
      ((now - start) / 1000) * UNIFORMS.timeScale, UNIFORMS.colorCount);
    gl.uniform4f(uni.space, UNIFORMS.offsetX, UNIFORMS.offsetY, mouseX, mouseY);
    gl.uniform4f(uni.cursor, UNIFORMS.cursorEnabled ? cursorPresence : 0,
      UNIFORMS.cursorEffect, UNIFORMS.cursorStrength, UNIFORMS.cursorRadius);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    if (window.HeroPerf) HeroPerf.add("shader", _tp);
    var settling = Math.abs(targetX - mouseX) > 0.001 ||
                   Math.abs(targetY - mouseY) > 0.001 ||
                   Math.abs(targetPresence - cursorPresence) > 0.001;
    if (timeAnimated || settling) requestRender(); else lastNow = null;
  }

  var onLayout = function () { bounds = canvas.getBoundingClientRect(); resizeCanvas(); updatePointerTarget(); requestRender(); };
  window.addEventListener("resize", onLayout);
  if (UNIFORMS.cursorEnabled) {
    window.addEventListener("pointermove", onPointerMove, { passive: true });
    window.addEventListener("pointercancel", onPointerLeave);
    window.addEventListener("scroll", onLayout, true);
    window.addEventListener("blur", onPointerLeave);
    document.documentElement.addEventListener("pointerleave", onPointerLeave);
  }

  var io = new IntersectionObserver(function (es) {
    inView = es[0] ? es[0].isIntersecting : true;
    if (inView) requestRender();
    else if (raf !== 0) { cancelAnimationFrame(raf); raf = 0; lastNow = null; }
  });
  io.observe(canvas);

  var onVis = function () {
    visible = document.visibilityState === "visible";
    if (visible) requestRender();
    else if (raf !== 0) { cancelAnimationFrame(raf); raf = 0; lastNow = null; }
  };
  document.addEventListener("visibilitychange", onVis);

  // WORK detail overlay pauses/resumes the shader (work-detail.js dispatches this).
  window.addEventListener("work:overlay", function (e) {
    paused = !!(e.detail && e.detail.open);
    if (paused) { if (raf !== 0) { cancelAnimationFrame(raf); raf = 0; lastNow = null; } }
    else requestRender();
  });

  resizeCanvas();
  requestRender();
})();
